    --text-muted: #a0a0a0;
    --border-color: #333333;
    --button-hover: rgba(255, 255, 255, 0.08);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    line-height: 1.6;
}

main {
    width: 100%;
    max-width: 900px;
    padding: 2rem;
}

.preview-container {
    background-color: var(--surface-color);
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
    text-align: center;
}

h1 {
    margin-bottom: 1.5rem;
    font-weight: 500;
}

.image-wrapper {
    margin-bottom: 2rem;
    border-radius: 8px;
    overflow: hidden;
    background-color: #000;
    display: flex;
    justify-content: center;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

.actions {
    display: flex;
    justify-content: center;
}

.btn {
    padding: 0.75rem 1.5rem;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
    border: none;
}

.btn:active {
    transform: scale(0.98);
}

.btn-danger {
    background-color: var(--danger-color);
    color: #000;
}

.btn-danger:hover {
    background-color: #e28a99;
}

.btn-secondary {
    background-color: transparent;
    color: var(--text-color);
    border: 1px solid var(--border-color);
}

.btn-secondary:hover {
    background-color: var(--button-hover);
}

/* Modal styles */
dialog {
    background: var(--surface-color);
    color: var(--text-color);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 0;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
}

dialog::backdrop {
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(4px);
}

.modal-content {
    padding: 2rem;
}

#modal-title {
    margin-bottom: 1rem;
    font-size: 1.5rem;
}

#modal-description {
    color: var(--text-muted);
    margin-bottom: 2rem;
}

.modal-actions {
    display: flex;
    gap: 1rem;
    justify-content: flex-end;
}

/* Ensure focus visibility */
.btn:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}
